import os, re, json

pat = re.compile(r'zero[- ]shot', re.I)
ret = re.compile(r'retrieval', re.I)

def dicts(o):
    if isinstance(o, dict):
        yield o
        for v in o.values():
            yield from dicts(v)
    elif isinstance(o, list):
        for i in o:
            yield from dicts(i)

def authors(o):
    out = []
    def walk(x):
        if isinstance(x, dict):
            for k, v in x.items():
                if k.lower() in {'author', 'authors', 'author_name', 'author_names', 'by'}:
                    out.append(v)
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for i in x:
                walk(i)
    walk(o)
    return out

count = 0
for root, _, files in os.walk('/corpus'):
    for fn in files:
        p = os.path.join(root, fn)
        try:
            s = open(p, encoding='utf-8', errors='ignore').read()
        except Exception:
            continue
        if not (pat.search(s) and ret.search(s)):
            continue
        print('FILE', p)
        parsed = False
        try:
            data = json.loads(s)
            if not isinstance(data, (dict, list)):
                raise ValueError
            parsed = True
            for obj in dicts(data):
                t = json.dumps(obj, ensure_ascii=False)
                if pat.search(t) and ret.search(t):
                    a = authors(obj)
                    print('MATCH', p, 'KEYS', list(obj.keys()) if isinstance(obj, dict) else type(obj).__name__, 'AUTHORS', a)
                    count += 1
                    if count >= 30:
                        break
        except Exception:
            pass
        if not parsed:
            for line in s.splitlines():
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                    t = json.dumps(obj, ensure_ascii=False)
